/**
 * The Spanish corrections ledger (grammar design §9.6 and the controller's rulings). Every row names the page cell
 * (verb, catalogue target after the remaps, subject slot or variant column), the text the page prints, the literal
 * text that replaces it (never generated by the engine) or `null` for a cell that has no form, a reason and its
 * authority. The RAE pages (rae.es, dle.rae.es) refused automated reading and no browser was available, so a reason
 * whose authority is an RAE page says which page was read instead.
 */
import { startCorrection } from '../model.ts';
import type { CorpusCell, CorpusCorrection, CorpusFile } from '../model.ts';

const dpd = (entry: string): string => `https://www.rae.es/dpd/${entry}`;
const dle = (entry: string): string => `https://dle.rae.es/${entry}`;
const novedades = 'https://www.edu.xunta.gal/centros/cpicovaterrena/system/files/Principales%20novedades%20de%20la%20Ortograf%C3%ADa%20de%20la%20RAE.pdf';
const notRead = (read: string): string => `(RAE page not read: rae.es refuses automated reading; read instead: ${read})`;

interface Row {
  readonly verb: string;
  /** `mood.tense|slot`, with the slot a subject id or a variant column (`ra`, `se`, `irregular`), or empty. */
  readonly cell: string;
  readonly from: string;
  readonly to: readonly string[] | null;
  readonly reason: string;
  readonly source: string;
}

const slots = ['1sg', '2sg', '3sg', '1pl', '2pl', '3pl'] as const;
const pronounsOf = ['yo', 'tú', 'él', 'nosotros', 'vosotros', 'ellos'] as const;

const abolirReason = `abolir is now conjugated in full, its forms with a stressed root included (NGLE 2009; DPD «abolir») ${notRead('en.wiktionary.org/wiki/abolir, which prints yo abolo, tú aboles')}; the page leaves them empty.`;
const ahincarReason = `A stressed i next to a vowel takes the tilde even with an h between them (Ortografía 2010, DPD «tilde²» §2.2.2; DLE ahincar) ${notRead('en.wiktionary.org/wiki/ahincar: ahínco, ahíncan, ahínque')}.`;
const monosyllableReason = 'Since the Ortografía of 2010 a word with a diphthong or triphthong that is one written syllable takes no tilde (guie, guio, guiais, rio, riais): the RAE summary of the novedades, item 4, read.';
const solerReason = `soler lacks only the future, the conditional and the imperative; its compound tenses, gerund and participle exist though they are rare (DPD «soler») ${notRead('en.wiktionary.org/wiki/soler, which lists soliendo and solido as rare but acceptable')}.`;

/** abolir: the 29 cells the page leaves empty or cuts off. */
const abolir: readonly Row[] = [
  ['indicative.present|1sg', 'yo abolo'], ['indicative.present|2sg', 'tú aboles'], ['indicative.present|3sg', 'él abole'], ['indicative.present|3pl', 'ellos abolen'],
  ['indicative.perfect|1sg', 'yo he abolido'], ['indicative.perfect|2sg', 'tú has abolido'], ['indicative.perfect|3sg', 'él ha abolido'], ['indicative.perfect|3pl', 'ellos han abolido'],
  ['subjunctive.present|1sg', 'que yo abola'], ['subjunctive.present|2sg', 'que tú abolas'], ['subjunctive.present|3sg', 'que él abola'],
  ['subjunctive.present|1pl', 'que nosotros abolamos'], ['subjunctive.present|2pl', 'que vosotros aboláis'], ['subjunctive.present|3pl', 'que ellos abolan'],
  ['subjunctive.past|1sg', 'que yo haya abolido'], ['subjunctive.past|2sg', 'que tú hayas abolido'], ['subjunctive.past|3sg', 'que él haya abolido'],
  ['subjunctive.past|1pl', 'que nosotros hayamos abolido'], ['subjunctive.past|2pl', 'que vosotros hayáis abolido'], ['subjunctive.past|3pl', 'que ellos hayan abolido'],
  ['imperative.present|2sg', 'abole'], ['imperative.present|2sg.formal', 'abola'], ['imperative.present|1pl', 'abolamos'], ['imperative.present|2pl.formal', 'abolan'],
  ['imperative.negative|2sg', 'no abolas'], ['imperative.negative|2sg.formal', 'no abola'], ['imperative.negative|1pl', 'no abolamos'], ['imperative.negative|2pl.formal', 'no abolan'],
].map(([cell, to]) => ({ verb: 'abolir', cell: cell!, from: '-', to: [to!], reason: abolirReason, source: dpd('abolir') }));

/** soler: the compound tenses, the compound infinitive and gerund, the gerund and the participle the page leaves empty. */
const soler: readonly Row[] = [
  ...['he', 'has', 'ha', 'hemos', 'habéis', 'han'].map((aux, i) => [`indicative.perfect|${slots[i]}`, `${pronounsOf[i]} ${aux} solido`]),
  ...['había', 'habías', 'había', 'habíamos', 'habíais', 'habían'].map((aux, i) => [`indicative.pluperfect|${slots[i]}`, `${pronounsOf[i]} ${aux} solido`]),
  ...['hube', 'hubiste', 'hubo', 'hubimos', 'hubisteis', 'hubieron'].map((aux, i) => [`indicative.past_anterior|${slots[i]}`, `${pronounsOf[i]} ${aux} solido`]),
  ...['haya', 'hayas', 'haya', 'hayamos', 'hayáis', 'hayan'].map((aux, i) => [`subjunctive.past|${slots[i]}`, `que ${pronounsOf[i]} ${aux} solido`]),
  ...['hubiera', 'hubieras', 'hubiera', 'hubiéramos', 'hubierais', 'hubieran'].map((aux, i) => [`subjunctive.pluperfect|ra|${slots[i]}`, `que ${pronounsOf[i]} ${aux} solido`]),
  ...['hubiese', 'hubieses', 'hubiese', 'hubiésemos', 'hubieseis', 'hubiesen'].map((aux, i) => [`subjunctive.pluperfect|se|${slots[i]}`, `que ${pronounsOf[i]} ${aux} solido`]),
  ['infinitive.past|', 'haber solido'], ['gerund.present|', 'soliendo'], ['gerund.past|', 'habiendo solido'], ['participle.past|', 'solido'],
].map(([cell, to]) => ({ verb: 'soler', cell: cell!, from: '-', to: [to!], reason: solerReason, source: dpd('soler') }));

const rows: readonly Row[] = [
  ...abolir,
  {
    verb: 'abolir', cell: 'imperative.negative|2pl', from: 'no abol-', to: ['no aboláis'], source: dpd('abolir'),
    reason: `The page cuts the vosotros form off after the stem; it is the present subjunctive aboláis (DPD «abolir») ${notRead('en.wiktionary.org/wiki/abolir')}.`,
  },
  {
    verb: 'adquirir', cell: 'indicative.simple_past|2sg', from: 'tú adquiste', to: ['tú adquiriste'], source: dle('adquirir'),
    reason: `The preterite keeps the whole stem adquir-: adquiriste; adquiste drops a syllable (DLE adquirir) ${notRead('en.wiktionary.org/wiki/adquirir')}.`,
  },
  {
    verb: 'adquirir', cell: 'indicative.simple_past|2pl', from: 'vosotros adquisteis', to: ['vosotros adquiristeis'], source: dle('adquirir'),
    reason: `The preterite keeps the whole stem adquir-: adquiristeis; adquisteis drops a syllable (DLE adquirir) ${notRead('en.wiktionary.org/wiki/adquirir')}.`,
  },
  ...[
    ['indicative.present|1sg', 'yo ahinco', 'yo ahínco'], ['indicative.present|2sg', 'tú ahincas', 'tú ahíncas'], ['indicative.present|3sg', 'él ahinca', 'él ahínca'],
    ['indicative.present|3pl', 'ellos ahincan', 'ellos ahíncan'], ['subjunctive.present|1sg', 'que yo ahinque', 'que yo ahínque'],
    ['subjunctive.present|2sg', 'que tú ahinques', 'que tú ahínques'], ['subjunctive.present|3sg', 'que él ahinque', 'que él ahínque'],
    ['subjunctive.present|3pl', 'que ellos ahinquen', 'que ellos ahínquen'], ['imperative.present|2sg', 'ahinca', 'ahínca'],
    ['imperative.present|2sg.formal', 'ahinque', 'ahínque'], ['imperative.present|2pl.formal', 'ahinquen', 'ahínquen'],
    ['imperative.negative|2sg', 'no ahinques', 'no ahínques'], ['imperative.negative|2sg.formal', 'no ahinque', 'no ahínque'],
    ['imperative.negative|2pl.formal', 'no ahinquen', 'no ahínquen'],
  ].map(([cell, from, to]) => ({ verb: 'ahincar', cell: cell!, from: from!, to: [to!], reason: ahincarReason, source: dle('ahincar') })),
  ...[
    ['indicative.present|2pl', 'vosotros guiáis', 'vosotros guiais'], ['indicative.simple_past|1sg', 'yo guié', 'yo guie'],
    ['indicative.simple_past|3sg', 'él guió', 'él guio'], ['subjunctive.present|2pl', 'que vosotros guiéis', 'que vosotros guieis'],
    ['imperative.negative|2pl', 'no guiéis', 'no guieis'],
  ].map(([cell, from, to]) => ({ verb: 'guiar', cell: cell!, from: from!, to: [to!], reason: monosyllableReason, source: novedades })),
  ...[
    ['indicative.simple_past|3sg', 'él rió', 'él rio'], ['subjunctive.present|2pl', 'que vosotros riáis', 'que vosotros riais'],
    ['imperative.negative|2pl', 'no riáis', 'no riais'],
  ].map(([cell, from, to]) => ({ verb: 'reír', cell: cell!, from: from!, to: [to!], reason: monosyllableReason, source: novedades })),
  {
    verb: 'podrir', cell: 'indicative.simple_past|1sg', from: 'yo pudrí/podrí', to: ['yo pudrí'], source: dpd('pudrir'),
    reason: `pudrir and podrir are one verb with pudr- in every form but the participle podrido (DPD «pudrir») ${notRead('en.wiktionary.org/wiki/pudrir: pudrí, pudriré')}; podrí is a regional variant the engine does not generate.`,
  },
  {
    verb: 'podrir', cell: 'indicative.future|1sg', from: 'yo pudriré/podriré', to: ['yo pudriré'], source: dpd('pudrir'),
    reason: `pudrir and podrir are one verb with pudr- in every form but the participle podrido (DPD «pudrir») ${notRead('en.wiktionary.org/wiki/pudrir: pudrí, pudriré')}; podriré is a regional variant the engine does not generate.`,
  },
  {
    verb: 'salir', cell: 'conditional.present|2sg', from: 'tú saldías', to: ['tú saldrías'], source: dle('salir'),
    reason: `The conditional is built on the future stem saldr- (saldré, saldría): saldrías; the page drops the r (DLE salir) ${notRead('none; the other five persons on the page have saldr-')}.`,
  },
  {
    verb: 'valer', cell: 'conditional.present|2sg', from: 'tú valdías', to: ['tú valdrías'], source: dle('valer'),
    reason: `The conditional is built on the future stem valdr- (valdré, valdría): valdrías; the page drops the r (DLE valer) ${notRead('none; the other five persons on the page have valdr-')}.`,
  },
  ...soler,
  {
    verb: 'elegir', cell: 'participle.past|irregular', from: 'electo', to: null, source: 'https://www.rae.es/gram%C3%A1tica/morfolog%C3%ADa/',
    reason: `electo is an adjective (el presidente electo), not a participle of elegir; only freír, imprimir and proveer have two participles in use (NGLE §4.12) ${notRead('en.wiktionary.org/wiki/elegir: compound tenses take only elegido')}.`,
  },
];

/** The key of a cell: its catalogue target, then its variant column and its subject slot where it has them. */
function keyOf(cell: CorpusCell): string {
  const slot = [cell.variant?.pattern, cell.subject].filter(part => part !== undefined).join('|');
  return `${cell.target.mood}.${cell.target.tense}|${slot}`;
}

const byKey = new Map(rows.map(row => [`${row.verb}|${row.cell}`, row]));

/** The ledger's correction of one cell, or null; a row whose page text has changed fails the import. */
export function spanishCorrection(file: CorpusFile, cell: CorpusCell, index: number): CorpusCorrection | null {
  const draft = startCorrection(file, cell, index);
  const row = byKey.get(`${file.infinitive}|${keyOf(cell)}`);
  if (row !== undefined) {
    if (cell.original !== row.from) throw new Error(`es ledger: ${file.infinitive} ${row.cell} prints ${cell.original}, not ${row.from}.`);
    draft.expected = row.to === null ? [] : [...row.to];
    draft.unavailable = row.to === null;
    draft.note(row.reason, row.source);
  }
  if (file.infinitive === 'llover' && !cell.sourceUnavailable) {
    draft.change(
      `A weather verb has no subject, so its forms take no pronoun: llueve, ha llovido, que llueva (NGLE §4.14; DPD «llover») ${notRead('en.wiktionary.org/wiki/llover, which labels it impersonal')}.`,
      dpd('llover'), text => text.replace(/^(que )?él /u, '$1'),
    );
  }
  return draft.finish();
}

/** The number of ledger rows, for the guards. */
export const spanishLedgerRows = rows.length;
